  void createWallet(Function(WalletAddress) onResult) async { 
     var walletAddressMap = GetStorage().read(PreferenceKey.walletAddress); 
     WalletAddress? walletAddress; 
     var user = Get.find().userRx.value; 
     if (walletAddressMap != null) { 
       walletAddress = WalletAddress.fromJson(walletAddressMap); 
     } 
     if (walletAddress != null && walletAddress.userId == user.id) { 
       var pk = await encryptDecrypt(walletAddress.encryptedPK ?? "", false); 
       walletAddress.privateKey = pk; 
       onResult(walletAddress); 
     } else { 
       showLoadingDialog(); 
       APIRepository().createWallet("", "").then((resp) async { 
         hideLoadingDialog(); 
         if (resp.success) { 
           var walletAddress = WalletAddress(); 
           walletAddress.userId = user.id; 
           walletAddress.address = resp.data[APIConstants.kAddress]; 
           walletAddress.publicKey = resp.data[APIConstants.kPublicKey]; 
           walletAddress.encryptedPK = resp.data[APIConstants.kPrivateKey]; 
           var epk = 
               await encryptDecrypt(walletAddress.encryptedPK ?? "", false); 
           walletAddress.privateKey = epk; 
           onResult(walletAddress); 

           walletAddress.privateKey = ""; 
           GetStorage() 
               .write(PreferenceKey.walletAddress, walletAddress.toJson()); 
         } else { 
           showToast(resp.message, isError: true); 
         } 
       }, onError: (err) { 
         hideLoadingDialog(); 
         showToast(err.toString(), isError: true); 
       }); 
     } 
   } 

   void storeWallet(WalletAddress walletAddress) { 
     showLoadingDialog(); 
     APIRepository() 
         .storeWallet(walletAddress.address ?? "", walletAddress.publicKey ?? "") 
         .then((resp) { 
        
       if (resp.success) { 
         hideLoadingDialog(); 
         Get.back(); 
         getMyWallet(); 
       } else { 
         showToast(resp.message, isError: true); 
       } 
     }, onError: (err) { 
       hideLoadingDialog(); 
       showToast(err.toString(), isError: true); 
     }); 
   } 

   Future encryptDecrypt(String key, bool isEncrypt) async { 
     showLoadingDialog(); 
     try { 
       var resp = await APIRepository().encryptDecrypt(key, isEncrypt); 
       hideLoadingDialog(); 
       if (resp.success) { 
         return resp.data as String?; 
       } else { 
         showToast(resp.message, isError: true); 
         return null; 
       } 
     } catch (e) { 
       hideLoadingDialog(); 
       showToast(e.toString(), isError: true); 
       return null; 
     } 
   }

