#include "HX711.h"
HX711 loadcell;

// 1. HX711 circuit wiring
const int LOADCELL\_DOUT\_PIN = 2;
const int LOADCELL\_SCK\_PIN = 3;

#define DOUT 3
#define CLK 2

HX711 scale;
float calibration\_factor = -2380650;

void setup() {
 Serial.begin(9600);
 // Serial.println("HX711 Calibration");
 // Serial.println("Remove all weight from scale");
 // Serial.println("After readings begin, place known weight on scale"); 
 // Serial.println("Press a,s,d,f to increase calibration factor by 10,100,1000,10000 respectively");
 // Serial.println("Press z,x,c,v to decrease calibration factor by 10,100,1000,10000 respectively");
 // Serial.println("Press t for tare"); 

 scale.begin(DOUT, CLK);
 scale.set\_scale();
 scale.tare(); 

 long zero\_factor = scale.read\_average(); 
 Serial.print("Zero factor: "); 
 Serial.println(zero\_factor);
}

void loop() {
 scale.set\_scale(calibration\_factor); 

 Serial.print("Reading: ");
 Serial.print(scale.get\_units()\*1000, 1);
 Serial.print(" g"); 

 Serial.print(" calibration\_factor: "); 
 Serial.print(calibration\_factor); 
 Serial.println();

 if (Serial.available()) {
 char temp = Serial.read(); 

 if (temp == '+' || temp == 'a')
 calibration\_factor += 10;
 else if (temp == '-' || temp == 'z')
 calibration\_factor -= 10;
 else if (temp == 's')
 calibration\_factor += 100;
 else if (temp == 'x')
 calibration\_factor -= 100;
 else if (temp == 'd')
 calibration\_factor += 1000;
 else if (temp == 'c')
 calibration\_factor -= 1000;
 else if (temp == 'f')
 calibration\_factor += 10000;
 else if (temp == 'v')
 calibration\_factor -= 10000;
 else if (temp == 't')
 scale.tare(); 
 }
}

