 {
 set\_start\_position();

 search::Context::\_on\_iter = on\_iteration;

 \_options.emplace("algorithm", std::make\_shared(\_algorithm));
 \_options.emplace("best opening", std::make\_shared("Best Opening", \_best\_book\_move));
 \_options.emplace("debug", std::make\_shared("Debug", \_debug));
 \_options.emplace("ownbook", std::make\_shared("OwnBook", \_use\_opening\_book));
 \_options.emplace("ponder", std::make\_shared("Ponder", \_ponder));
 \_options.emplace("evalfile", std::make\_shared(\_eval\_file));
 \_options.emplace("syzygypath", std::make\_shared());
 }

 static bool output\_expected() { return \_output\_expected.load(std::memory\_order\_relaxed); }
 void run();

private:
 void dispatch(const std::string &, const Arguments &args);

