using ThreadPool = thread\_pool;

class UCI
{
 using Arguments = std::vector;
 using EngineOptions = std::map>;

 static constexpr int max\_depth = PLY\_MAX;

public:
 UCI(const std::string &name, const std::string &version)
 : \_name(name)
 , \_version(version)
 , \_use\_opening\_book(search::Context::\_book\_init(\_book))
 {
 set\_start\_position();

 search::Context::\_on\_iter = on\_iteration;

 \_options.emplace("algorithm", std::make\_shared(\_algorithm));
 \_options.emplace("best opening", std::make\_shared("Best Opening", \_best\_book\_move));
 \_options.emplace("debug", std::make\_shared("Debug", \_debug));
 \_options.emplace("ownbook", std::make\_shared("OwnBook", \_use\_opening\_book));
 \_options.emplace("ponder", std::make\_shared("Ponder", \_ponder));
 \_options.emplace("evalfile", std::make\_shared(\_eval\_file));
 \_options.emplace("syzygypath", std::make\_shared());
 }

 static bool output\_expected() { return \_output\_expected.load(std::memory\_order\_relaxed); }
 void run();

private:
 void dispatch(const std::string &, const Arguments &args);

 /\*\* UCI commands \*/
 void go(const Arguments &args);
 void isready();
 void ponderhit();
 void position(const Arguments &args);
 void setoption(const Arguments &args);
 void stop();
 void uci();
 void newgame();

 /\*\* Context callbacks \*/
 static void on\_iteration(PyObject \*, search::Context \*, const search::IterationInfo \*);

private:
 /\*\* position() helper \*/
 template  INLINE void apply\_moves(const T &moves)
 {
 \_last\_move = chess::BaseMove();
 \_ply\_count = 0;

 for (const auto &m : moves)
 if (m.size() >= 4)
 {
 chess::Square from, to;

 if (chess::parse\_square(m, from) && chess::parse\_square(std::string\_view(&m[2], 2), to))
 {
 const auto promo = m.size() > 4 ? chess::piece\_type(m[4]) : chess::PieceType::NONE;
 const auto move = chess::BaseMove(from, to, promo);
 const auto prev = \_buf.\_state;
 \_buf.\_state.apply\_move(move);
 chess::zobrist\_update(prev, move, \_buf.\_state);
 ASSERT(\_buf.\_state.\_hash == chess::zobrist\_hash(\_buf.\_state));
 /\* keep track of played moves, to detect repetitions \*/
 search::Context::\_history->emplace(\_buf.\_state);
 /\* update the halfmove clock \*/
 if (\_buf.\_state.capture\_value || prev.piece\_type\_at(from) == chess::PieceType::PAWN)
 search::Context::\_history->\_fifty = 0;
 else
 ++search::Context::\_history->\_fifty;
 \_last\_move = move;
 ++\_ply\_count;
 }
 }
 }

 INLINE search::Context &context() { return \*\_buf.as\_context(); }

 template 
 INLINE void output\_best\_move(bool request\_ponder = false)
 {
 if (output\_expected())
 {
 auto &ctxt = context();
 auto move = ctxt.\_best\_move;
 if (!move)
 if (auto first = ctxt.first\_valid\_move())
 move = \*first;
 if constexpr(synchronous)
 output\_best\_move(move, request\_ponder);
 else
 \_output\_pool->push\_task([this, move, request\_ponder] {
 output\_best\_move(move, request\_ponder);
 });
 }
 }

 INLINE void output\_best\_move(const chess::BaseMove &move, bool request\_ponder = false)
 {
 ASSERT(output\_expected());
 \_output\_expected = false;

 if (!move)
 {
 output("resign");
 }
 else
 {
 if (request\_ponder && \_ponder)
 {
 const auto &pv = \_tt.get\_pv();
 if (pv.size() > 2 && pv[1] == move)
 {
 output(std::format("bestmove {} ponder {}", move.uci(), pv[2].uci()));
 return;
 }
 }
 output(std::format("bestmove {}", move.uci()));
 }
 }

 template 
 INLINE void invoke(const std::string &cmd, F f, const Arguments &args)
 {
 if constexpr (arity{} == 0)
 {
 if (args.size() > 1)
 log\_warning(std::format("extraneous arguments: {}", cmd));
 (this->\*f)();
 }
 else
 {
 (this->\*f)(args);
 }
 }

 INLINE void set\_start\_position()
 {
 \_buf.\_state = chess::State();
 \_buf.\_state.castling\_rights = chess::BB\_DEFAULT\_CASTLING\_RIGHTS;
 chess::epd::parse\_pos(START\_POS, \_buf.\_state);
 \_buf.\_state.rehash();
 \_book\_depth = max\_depth;
 }

 /\*\* think on opponent's time \*/
 void ponder();

 /\*\* iterative deepening search \*/
 score\_t search();

 search::Algorithm \_algorithm = search::Algorithm::MTDF;
 search::ContextBuffer \_buf;
 search::TranspositionTable \_tt;
 std::string \_book = "book.bin";
 std::string \_eval\_file = NNUE\_EVAL\_FILE;
 std::atomic\_int \_extended\_time = 0; /\* for pondering \*/
 int \_book\_depth = max\_depth;
 int \_depth = max\_depth;
 int \_ply\_count = 0;
 score\_t \_score = 0;
 EngineOptions \_options;
 const std::string \_name;
 const std::string \_version; /\* engine version \*/
 static std::unique\_ptr \_compute\_pool;
 static std::unique\_ptr \_output\_pool;
 static std::atomic\_bool \_output\_expected;
 bool \_ponder = false;
 bool \_use\_opening\_book = false;
 bool \_best\_book\_move = false;
 chess::BaseMove \_last\_move;
};

std::unique\_ptr UCI::\_output\_pool(std::make\_unique(1));
std::unique\_ptr UCI::\_compute\_pool(std::make\_unique(1));

std::atomic\_bool UCI::\_output\_expected(false);

/\*\* Estimate number of moves (not plies!) until mate. \*/
static INLINE int mate\_distance(score\_t score, const search::PV &pv)
{
 return std::copysign((std::max(CHECKMATE - std::abs(score), pv.size()) + 1) / 2, score);
}

/\*\* Info sent to the GUI. \*/
struct Info : public search::IterationInfo
{
 const int eval\_depth;
 const int hashfull;
 const int iteration;
 search::PV\* const pv;
 static std::array pvs;

 Info(const search::Context& ctxt, const IterationInfo& info)
 : IterationInfo(info)
 , eval\_depth(ctxt.get\_tt()->\_eval\_depth)
 , hashfull(search::TranspositionTable::usage() \* 10)
 , iteration(ctxt.iteration())
 , pv(&pvs[std::min(pvs.size() - 1, iteration)])
 {
 pv->assign(ctxt.get\_pv().begin() + 1, ctxt.get\_pv().end());
 }
};

/\* Hold PVs for pending output tasks \*/
std::array Info::pvs;

static void INLINE output\_info(std::ostream& out, const Info& info)
{
 constexpr auto MATE\_DIST\_MAX = 10;
 constexpr auto TIME\_LOW = 25; /\* millisec \*/

 const auto ms = info.milliseconds;
 const auto time\_limit = search::Context::time\_limit();

 if (time\_limit > 0 && time\_limit <= ms + TIME\_LOW)
 {
 output(out, "info depth ", info.iteration, " score cp ", info.score);
 }
 else
 {
 output(out, "info depth ", info.iteration, " seldepth ", info.eval\_depth);
 if (std::abs(info.score) > CHECKMATE - MATE\_DIST\_MAX)
 output(out, " score mate ", mate\_distance(info.score, \*info.pv));
 else
 output(out, " score cp ", info.score);

 output(out,
 " time ", ms,
 " nodes ", info.nodes,
 " nps ", int(info.knps \* 1000),
 " hashfull ", info.hashfull);
 out << " pv ";
 for (const auto &m : \*info.pv)
 out << m << " ";
 }
}

static void INLINE output\_info(const Info& info)
{
 output\_info(std::cout, info);
 std::cout << std::endl;

 if (\_debug)
 {
 std::ostringstream out;
 output\_info(out << "<<< ", info);
 log\_debug(out.str());
 }
}

/\* static \*/
INLINE void UCI::on\_iteration(PyObject \*, search::Context \*ctxt, const search::IterationInfo \*iter\_info)
{
 if (ctxt && iter\_info)
 {
 const Info info(\*ctxt, \*iter\_info);
 \_output\_pool->push\_task([info] {
 output\_info(info);
 });
 }
}

void UCI::run()
{
 std::string cmd;
 while (true)
 {
 std::getline(std::cin, cmd);
 if (std::cin.fail() || std::cin.eof())
 {
 stop();
 break;
 }
 const auto nl = cmd.find\_last\_not\_of("\n\r");
 if (nl != std::string::npos)
 cmd.erase(nl + 1);
 if (cmd.empty())
 continue;
 LOG\_DEBUG(std::format(">>> {}", cmd));
 if (cmd == "quit")
 {
 \_output\_expected = false;
 stop();
 output("info string good bye");
 break;
 }

 Arguments args;
 /\* tokenize command \*/
 std::ranges::for\_each(
 std::views::lazy\_split(cmd, std::string\_view(" ")),
 [&](auto const &tok)
 {
 if (!tok.empty())
 args.emplace\_back(std::string\_view(&\*tok.begin(), std::ranges::distance(tok)));
 });

 if (!args.empty())
 dispatch(cmd, args);
 }
}

INLINE void UCI::dispatch(const std::string &cmd, const Arguments &args)
{
 ASSERT(!args.empty());
 const auto iter = commands.find(args.front());
 if (iter == commands.end())
 {
 log\_error("unknown command: " + cmd);
 }
 else
 {
 switch (iter->second)
 {
 case Command::GO:
 invoke(cmd, &UCI::go, args);
 break;
 case Command::ISREADY:
 invoke(cmd, &UCI::isready, args);
 break;
 case Command::PONDERHIT:
 invoke(cmd, &UCI::ponderhit, args);
 break;
 case Command::POSITION:
 invoke(cmd, &UCI::position, args);
 break;
 case Command::SETOPTION:
 invoke(cmd, &UCI::setoption, args);
 break;
 case Command::STOP:
 invoke(cmd, &UCI::stop, args);
 break;
 case Command::UCI:
 invoke(cmd, &UCI::uci, args);
 break;
 case Command::UCINEWGAME:
 invoke(cmd, &UCI::newgame, args);
 break;
 default:
 break;
 }
 }
}

template 
INLINE const auto &next(const T &v, size\_t &i)
{
 static typename T::value\_type empty;
 return ++i < v.size() ? v[i] : empty;
}

void UCI::go(const Arguments &args)
{
 stop();

 bool explicit\_movetime = false, do\_analysis = false, do\_ponder = false;
 int movestogo = 40, movetime = 0;
 int time\_remaining[] = {0, 0};
 auto turn = \_buf.\_state.turn;

 \_depth = max\_depth;

 for (size\_t i = 1; i < args.size(); ++i)
 {
 const auto &a = args[i];
 if (a == "depth")
 {
 \_depth = to\_int(next(args, i));
 do\_analysis = true;
 }
 else if (a == "movetime")
 {
 movetime = to\_int(next(args, i));
 explicit\_movetime = true;
 }
 else if (a == "movestogo")
 {
 movestogo = to\_int(next(args, i));
 }
 else if (a == "wtime")
 {
 time\_remaining[chess::WHITE] = to\_int(next(args, i));
 }
 else if (a == "btime")
 {
 time\_remaining[chess::BLACK] = to\_int(next(args, i));
 }
 else if (a == "ponder")
 {
 do\_ponder = true;
 }
 else if (a == "infinite")
 {
 movetime = -1;
 do\_analysis = true;
 }
 }
 /\* initialize search context \*/
 auto ctxt = new (\_buf.as\_context()) search::Context();
 ctxt->\_state = &\_buf.\_state;

 if (!movetime)
 movetime = time\_remaining[turn] / std::max(movestogo, 40);
 LOG\_DEBUG(std::format("movetime {}, movestogo {}", movetime, movestogo));

 \_extended\_time = 0;
 \_output\_expected = true;

 if (do\_ponder)
 {
 \_extended\_time = std::max(1, movetime);
 ctxt->set\_time\_limit\_ms(INFINITE);
 \_compute\_pool->push\_task([this]{ ponder(); });
 }
 else if (do\_analysis && !explicit\_movetime)
 {
 ctxt->set\_time\_limit\_ms(INFINITE);
 \_compute\_pool->push\_task([this]{ search(); output\_best\_move(); });
 }
 else
 {
 if (\_use\_opening\_book && \_ply\_count < \_book\_depth && !do\_analysis)
 {
 LOG\_DEBUG(std::format("lookup book\_depth={}, ply\_count={}", \_book\_depth, \_ply\_count));
 if (auto move = search::Context::\_book\_lookup(\_buf.\_state, \_best\_book\_move))
 {
 output\_best\_move(move);
 return;
 }
 else
 \_book\_depth = \_ply\_count;
 }
 ctxt->set\_time\_limit\_ms(movetime);
 if (!explicit\_movetime)
 ctxt->set\_time\_info(time\_remaining[turn], movestogo, \_score);

 \_compute\_pool->push\_task([this, movetime] {
 \_score = search();
 /\* Do not request to ponder below 100 ms per move. \*/
 output\_best\_move(movetime >= 100);
 });
 }
}

/\*\*
 \* This command must always be answered with "readyok" and can be sent also
 \* when the engine is calculating in which case the engine should also immediately
 \* answer with "readyok" without stopping the search.
 \*/
INLINE void UCI::isready()
{
 output("readyok");
}

void UCI::newgame()
{
 stop();
 search::TranspositionTable::clear\_shared\_hashtable();
 set\_start\_position();
}

/\*\*
 \* Runs on a background thread with infinite time, and expects that:
 \* either STOP is received; or
 \* PONDERHIT is received, which extends the search by \_extended\_time,
 \* then sets \_extended\_time to 0, to indicate to this function to send out
 \* the best move when the search finishes.
 \*
 \* Pondering may finish before PONDERHIT is received, in which case
 \* it resets \_extended\_time and does not output a move;
 \*
 \* the ponderhit handler will send out the best move instead, when PONDERHIT
 \* is received (thus avoiding "premature bestmove in ponder" errors).
 \*/
void UCI::ponder()
{
 LOG\_DEBUG(std::format("pondering, extended\_time={}", \_extended\_time.load()));
 search();
 if (\_extended\_time)
 \_extended\_time = 0;
 else
 output\_best\_move();
}

void UCI::ponderhit()
{
 if (int ext = \_extended\_time)
 {
 \_extended\_time = 0;
 context().set\_time\_limit\_ms(ext);
 }
 else
 {
 stop();
 }
}

void UCI::position(const Arguments &args)
{
 stop();

 bool in\_moves = false;
 Arguments fen, moves;

 for (const auto &a : std::ranges::subrange(args.begin() + 1, args.end()))
 {
 if (a == "fen")
 {
 in\_moves = false;
 }
 else if (a == "moves")
 {
 in\_moves = true;
 if (search::Context::\_history)
 search::Context::\_history->clear();
 else
 search::Context::\_history = std::make\_unique();
 }
 else if (a == "startpos")
 {
 set\_start\_position();
 in\_moves = false;
 }
 else if (in\_moves)
 {
 moves.emplace\_back(a);
 }
 else
 {
 fen.emplace\_back(a);
 }
 }
 if (fen.size() >= 4)
 {
 \_buf.\_state = chess::State();
 if ( !chess::epd::parse\_pos(fen[0], \_buf.\_state)
 || !chess::epd::parse\_side\_to\_move(fen[1], \_buf.\_state)
 || !chess::epd::parse\_castling(fen[2], \_buf.\_state)
 || !chess::epd::parse\_en\_passant\_target(fen[3], \_buf.\_state)
 )
 raise\_value\_error("fen={} {} {} {}", fen[0], fen[1], fen[2], fen[3]);
 }
 else if (!fen.empty())
 {
 raise\_value\_error("invalid token count {}, expected 4", fen.size());
 }
 apply\_moves(moves);
 LOG\_DEBUG(search::Context::epd(\_buf.\_state));
}

INLINE score\_t UCI::search()
{
 if (!search::Context::\_history)
 search::Context::\_history = std::make\_unique();

 \_tt.init();

 auto& ctxt = context();
 ctxt.set\_tt(&\_tt);

 ctxt.\_algorithm = \_algorithm;
 ctxt.\_max\_depth = 1;
 ctxt.\_move = \_last\_move;

 return search::iterative(ctxt, \_tt, \_depth + 1);
}

void UCI::setoption(const Arguments &args)
{
 Arguments name, value, \*acc = nullptr;

 for (const auto &a : std::ranges::subrange(args.begin() + 1, args.end()))
 {
 if (a == "name")
 acc = &name
 else if (a == "value")
 acc = &value
 else if (acc)
 acc->emplace\_back(a);
 }

 auto opt\_name = join(" ", name);
 auto iter = \_options.find(lowercase(opt\_name));
 if (iter != \_options.end())
 iter->second->set(join(" ", value));
 else
 log\_warning(\_\_func\_\_ + (": \"" + opt\_name + "\": not found"));
}

void UCI::stop()
{
 search::Context::set\_time\_limit\_ms(0);
 \_compute\_pool->wait\_for\_tasks([] { search::Context::cancel(); });
 \_output\_pool->wait\_for\_tasks();
 output\_best\_move();
}

void UCI::uci()
{
 std::ios\_base::sync\_with\_stdio(false);
 output(std::format("id name {}-{}", \_name, \_version));
 output("id author Cristi Vlasceanu");

 /\* refresh options \*/
 for (auto p : \_get\_param\_info())
 {
 auto name = p.first;
 /\* option names are case insensitive, and can contain \_single\_ spaces \*/
 \_options[lowercase(name)] = std::make\_shared(p.first, p.second);
 }
 /\* show available options \*/
 for (const auto &opt : \_options)
 {
 std::ostringstream opts;
 opt.second->print(opts << "option name ");
 output(opts.str());
 }
 output("uciok");
}

extern "C" void run\_uci\_loop(const char \*name, const char \*version, bool debug)
{
 \_debug = debug;
 std::string err;
 try
 {
 UCI uci(name, version);
 uci.run();
 }
 catch (const std::exception &e)
 {
 err = e.what();
 }
 catch (...)
 {
 err = "unknown exception";
 }
 if (!err.empty())
 raise\_runtime\_error(err.c\_str());
}
#else
extern "C" void run\_uci\_loop(const char \*, const char \*, bool)
{
 raise\_runtime\_error("Native UCI implementation is not enabled.");
}
#endif /\* NATIVE\_UCI \*/

